func TestEnsureCreatesOnce(t *testing.T) {
	vault := newVault(t)
	value := testSecrets()[EnvMasterKey]
	stored, err := Ensure(t.Context(), vault, testTarget, "gru-1", EnvMasterKey, func(context.Context) (string, error) { return value, nil })
