const (
	OrganizationName = "terrascale"
	ProjectName      = "ts-auth"
	// BootstrapUser is the acting user that creates the organization and so
	// becomes its owner; ts-auth has no users before it runs. It is a fixed
	// service identity, not a ts-auth user, and stays an admin after
	// EnsureOwner hands the ownership to a person.
	BootstrapUser = "01M4EB0GDPPHGJPPVY77EMZQKT"
)

// KeyScopes are the scopes of every project's TerraBase API key.
var KeyScopes = []string{"documents:read", "documents:write"}

// Project is one project of TerraScale's own organization, OrganizationName,
// with its database and the Vault keys of its project ID and API key.
type Project struct {
	Name, Database          string
	ProjectIDKey, APIKeyKey string
}

// Projects is the ouroboros table: TerraScale's own services keep their data
// in the production TerraBase, each in its own project and database, reached
// with its own API key.
var Projects = []Project{
	{Name: ProjectName, Database: Database, ProjectIDKey: EnvProjectID, APIKeyKey: EnvAPIKey},
	dashboard,
	// atlas is ts-atlas' store (ts-atlas docs/discovery-v1.md §Storage): the
	// Worker's ATLAS_STORE_URL names its database and ATLAS_STORE_KEY is
	// this key.
	{Name: "atlas", Database: "atlas", ProjectIDKey: "ATLAS_TERRABASE_PROJECT_ID", APIKeyKey: "ATLAS_STORE_KEY"},
}

// dashboard is ts-dashboard's project; fly-secrets hands it to the dashboard.
var dashboard = Project{Name: "ts-dashboard", Database: "dashboard",
	ProjectIDKey: "TS_DASHBOARD_TERRABASE_PROJECT_ID", APIKeyKey: "TS_DASHBOARD_TERRABASE_API_KEY"}

const (
	EnvMasterKey       = "TS_AUTH_MASTER_KEY"
	EnvAuditSigningKey = "TS_AUTH_AUDIT_SIGNING_KEY"
	EnvOperatorKey     = "TS_AUTH_OPERATOR_KEY"
	// EnvDashboardClientSecret is the ts-dashboard client's secret, which
	// ouroboros fly-secrets also hands the dashboard as TS_AUTH_CLIENT_SECRET.
	EnvDashboardClientSecret = "TS_AUTH_DASHBOARD_CLIENT_SECRET"
	EnvAPIKey                = "TS_AUTH_TERRASCALE_API_KEY"
	EnvProjectID             = "TS_AUTH_TERRASCALE_PROJECT_ID"
	// The signing owner publishes ring versions; replicas reopen this file.
	EnvSigningKeyRingFile = "TS_AUTH_SIGNING_KEY_RING_FILE"
)

// Settings the host agent owns.
const (
	EnvListen        = "TS_AUTH_LISTEN"
	EnvBundleExtract = terrabase.EnvBundleExtract
)

// Generated are the secrets ts-orch generates once: 32 random bytes, base64.
var Generated = []string{EnvMasterKey, EnvAuditSigningKey, EnvOperatorKey, EnvDashboardClientSecret}

// Secrets are the keys of the profile's secret refs.
var Secrets = []string{EnvMasterKey, EnvAuditSigningKey, EnvOperatorKey, EnvDashboardClientSecret, EnvAPIKey, EnvProjectID}

var (
	assetRE  = regexp.MustCompile(`^ts-auth-linux-(?:amd64|arm64)$`)
	apiKeyRE = regexp.MustCompile(`^[\x21-\x7e]+$`)
)

// validSecret checks one secret value without ever printing it.
func validSecret(key, value string) error {
	if slices.Contains(Generated, key) {
		decoded, err := base64.StdEncoding.Strict().DecodeString(value)
		// Strict still skips CR and LF; only the canonical form fits one line.
		if err != nil || len(decoded) != 32 || base64.StdEncoding.EncodeToString(decoded) != value {
			return fmt.Errorf("%s must be 32 bytes in base64", key)
		}
		return nil
	}
	if slices.ContainsFunc(Projects, func(project Project) bool { return project.ProjectIDKey == key }) {
		if !entityid.Valid(value) {
			return fmt.Errorf("%s must be a canonical uppercase ULID", key)
		}
		return nil
	}
	if !slices.ContainsFunc(Projects, func(project Project) bool { return project.APIKeyKey == key }) ||
		len(value) > 4096 || !apiKeyRE.MatchString(value) {
		return fmt.Errorf("%s must be 1 to 4096 printable characters without spaces", key)
	}
	return nil
}

// Name is the Vault secret holding key of scope, a cell such as gru-1: the
// scope, then the key lower-cased with hyphens for underscores. The key
// starts with its service, so TS_AUTH_MASTER_KEY of gru-1 is
// gru-1-ts-auth-master-key.
func Name(scope, key string) string {
	return scope + "-" + strings.ToLower(strings.ReplaceAll(key, "_", "-"))
}

// New returns a cryptographically random ULID, monotonic within a millisecond.
func New() string { return NewAt(time.Now()) }

// NewAt stamps an ID with the record's time. The entropy reader is shared and
// serialized because the library's monotonic reader is not concurrency-safe.
func NewAt(at time.Time) string {
	mu.Lock()
	defer mu.Unlock()
	return ulid.MustNew(ulid.Timestamp(at), entropy).String()
}

// Parse accepts only nonzero, uppercase, 26-character Crockford ULIDs.
func Parse(value string) (ulid.ULID, error) {
	id, err := ulid.ParseStrict(value)
	if err != nil || id == (ulid.ULID{}) || id.String() != value {
		return ulid.ULID{}, errors.New("entity ID must be a canonical uppercase ULID")
	}
	return id, nil
}

func Valid(value string) bool {
	_, err := Parse(value)
	return err == nil
}

func (u TSAuthUsers) UserID(ctx context.Context, email string) (string, error) {
	type user struct {
		ID            string `json:"id"`
		Email         string `json:"email"`
		EmailVerified bool   `json:"email_verified"`
		Anonymous     bool   `json:"is_anonymous"`
		Banned        bool   `json:"banned"`
	}
	var found []user
	for after := ""; ; {
		query := url.Values{"limit": {"100"}}
		if after != "" {
			query.Set("starting_after", after)
		}
		var page struct {
			Data []user `json:"data"`
		}
		target := u.URL + "/v1/" + url.PathEscape(u.Instance) + "/users?" + query.Encode()
		if err := (TerraBase{HTTP: u.HTTP}).call(ctx, http.MethodGet, target, http.Header{"Authorization": {"Bearer " + u.Key}}, nil, http.StatusOK, &page); err != nil {
			return "", fmt.Errorf("list ts-auth users: %w", err)
		}
		for _, item := range page.Data {
			if !entityid.Valid(item.ID) {
				return "", errors.New("ts-auth returned a noncanonical user ID")
			}
			if strings.EqualFold(item.Email, email) {
				found = append(found, item)
			}
		}
		if len(page.Data) < 100 || page.Data[len(page.Data)-1].ID == after {
			break
		}
		after = page.Data[len(page.Data)-1].ID
	}
	switch {
	case len(found) == 0:
		return "", fmt.Errorf("ts-auth instance %s has no user %s yet: sign in once with that address (for example on the dashboard), then rerun", u.Instance, email)
	case len(found) > 1:
		return "", fmt.Errorf("ts-auth instance %s has %d users %s; resolve that before rerunning", u.Instance, len(found), email)
	}
	owner := found[0]
	if !owner.EmailVerified || owner.Anonymous || owner.Banned {
		return "", fmt.Errorf("ts-auth user %s must have verified %s and be neither anonymous nor banned", owner.ID, email)
	}
	if !entityid.Valid(owner.ID) || owner.ID == BootstrapUser {
		return "", fmt.Errorf("ts-auth user %s has an unusable id", email)
	}
	return owner.ID, nil
}

func (t TerraBase) call(ctx context.Context, method, target string, headers http.Header, body any, status int, result any) error {
	var reader io.Reader
	if body != nil {
		data, err := json.Marshal(body)
		if err != nil {
			return err
		}
		reader = bytes.NewReader(data)
		headers.Set("Content-Type", "application/json")
	}
	request, err := http.NewRequestWithContext(ctx, method, target, reader)
	if err != nil {
		return err
	}
	request.Header = headers
	client := t.HTTP
	if client == nil {
		client = http.DefaultClient
	}
	path := request.URL.Path
	response, err := client.Do(request)
	if err != nil {
		return err
	}
	defer response.Body.Close()
	if response.StatusCode != status {
		return fmt.Errorf("%s %s: HTTP %d", method, path, response.StatusCode)
	}
	if result == nil {
		return nil
	}
	if err := json.UnmarshalRead(io.LimitReader(response.Body, 1<<20), result); err != nil {
		return fmt.Errorf("%s %s: decode reply: %w", method, path, err)
	}
	return nil
}

func RunOuroboros(ctx context.Context, args []string, output io.Writer, loadPlan func(string) (map[string]any, error)) error {
	if len(args) == 0 || args[0] == "help" || args[0] == "--help" || args[0] == "-h" {
		_, err := io.WriteString(output, ouroborosUsage())
		return err
	}
	flags := flag.NewFlagSet("ouroboros "+args[0], flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	plan := flags.String("plan", "", "reviewed cell plan (deploy/oci-region/plan.json)")
	clientURL := flags.String("client-url", "", "TerraBase member client listener, for example https://127.0.0.1:19465")
	adminURL := flags.String("admin-url", "", "TerraBase member admin listener, for example http://127.0.0.1:19464")
	member := flags.String("member", "", "TerraBase member node the client listener belongs to, for example gru-1-db-1")
	memberCA := flags.String("member-ca", "", "the cell's TerraBase member-ca.pem")
	credential := flags.String("dashboard-credential-file", "", "owner-only file holding the member's Management service credential (TERRABASE_MANAGEMENT_CREDENTIAL_FILE)")
	listener := flags.String("management-listener", "client", "listener serving the credential's Management API: client, or admin from TerraBase TS-519 on")
	ownerEmail := flags.String("owner-email", "", "verified address of the ts-auth user who becomes the owner")
	instance := flags.String("ts-auth-instance", "", "slug of the ts-auth instance the owner signed in to")
	keyFile := flags.String("ts-auth-key-file", "", "owner-only file holding that instance's sk_ management key")
	// The dashboard signs users in at gru's ts-auth.
	tsAuthURL := flags.String("ts-auth-url", PublicOrigin("gru"), "ts-auth's public origin")
	if err := flags.Parse(args[1:]); err != nil {
		return err
	}
	if flags.NArg() != 0 {
		return errors.New("unexpected ouroboros arguments")
	}
	switch args[0] {
	case "bootstrap":
		if *plan == "" || *clientURL == "" || *adminURL == "" || *member == "" || *memberCA == "" || *credential == "" {
			return errors.New("bootstrap requires --plan, --client-url, --admin-url, --member, --member-ca and --dashboard-credential-file")
		}
		if *listener != "client" && *listener != "admin" {
			return errors.New("--management-listener must be client or admin")
		}
		var users TSAuthUsers
		if *ownerEmail != "" || *instance != "" || *keyFile != "" {
			if address, err := mail.ParseAddress(*ownerEmail); err != nil || address.Address != *ownerEmail || *instance == "" || *keyFile == "" {
				return errors.New("--owner-email needs one plain address, --ts-auth-instance and --ts-auth-key-file")
			}
			if *listener != "admin" {
				return errors.New("--owner-email needs --management-listener admin: only TerraBase's admin listener adds a member (TS-535)")
			}
			var err error
			if users, err = tsAuthUsers(*tsAuthURL, *instance, *keyFile); err != nil {
				return err
			}
		}
		terraBase, err := memberClient(*clientURL, *adminURL, *member, *memberCA, *credential)
		if err != nil {
			return err
		}
		terraBase.ManagementOnAdmin = *listener == "admin"
		cell, target, client, bundles, err := OperatorVault(*plan, loadPlan)
		if err != nil {
			return err
		}
		organization, err := bootstrap(ctx, terraBase, client, bundles, target, cell, output)
		if err != nil || *ownerEmail == "" {
			return err
		}
		return own(ctx, terraBase, users, organization, *ownerEmail, output)
	case "fly-secrets":
		if *plan == "" {
			return errors.New("fly-secrets requires --plan")
		}
		cell, target, _, bundles, err := OperatorVault(*plan, loadPlan)
		if err != nil {
			return err
		}
		return flySecrets(ctx, bundles, target.VaultID, cell, output)
	default:
		_, _ = io.WriteString(output, ouroborosUsage())
		return fmt.Errorf("unknown ouroboros command %q", args[0])
	}
}

func tsAuthUsers(origin, instance, keyFile string) (TSAuthUsers, error) {
	if !strings.HasPrefix(origin, "https://") {
		return TSAuthUsers{}, errors.New("--ts-auth-url must be https://")
	}
	key, err := readOwnerOnly(keyFile, 4096)
	if err != nil {
		return TSAuthUsers{}, fmt.Errorf("--ts-auth-key-file: %w", err)
	}
	return TSAuthUsers{HTTP: &http.Client{Timeout: terraBaseRequestTimeout}, URL: strings.TrimSuffix(origin, "/"),
		Instance: instance, Key: strings.TrimSpace(string(key))}, nil
}

func readOwnerOnly(path string, limit int64) ([]byte, error) {
	file, err := os.OpenFile(path, os.O_RDONLY|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, err
	}
	if !info.Mode().IsRegular() || info.Mode().Perm()&0o077 != 0 || info.Size() > limit {
		return nil, errors.New("must be a regular owner-only file")
	}
	return io.ReadAll(io.LimitReader(file, limit))
}

func writeFile(t *testing.T, content string, mode os.FileMode) string {
	path := filepath.Join(t.TempDir(), "file")
	if err := os.WriteFile(path, []byte(content), mode); err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(path, mode); err != nil {
		t.Fatal(err)
	}
	return path
}

