var (
	secretOCIDRE = regexp.MustCompile(`^ocid1\.vaultsecret\.oc1\.[a-z0-9-]+\.[a-z0-9]+(?:\.[a-z0-9]+)*$`)
	nameRE       = regexp.MustCompile(`^[a-z0-9]+(?:-[a-z0-9]+)*$`)
)

func Ensure(ctx context.Context, client VaultClient, target Target, name, description string, value func(context.Context) (string, error)) (Stored, error) {
	stored := Stored{Secret: name}
	if err := safeEnv(); err != nil {
		return stored, err
	}
	id, provisioning, err := lookup(ctx, client, target, name)
	if err != nil || id != "" {
		stored.ID = id
		stored.Provisioning = provisioning
		return stored, err
	}
	secret, err := value(ctx)
	if err != nil {
		return stored, err
	}
	content := base64.StdEncoding.EncodeToString([]byte(secret))
	response, err := client.CreateSecret(ctx, ocivault.CreateSecretRequest{
		CreateSecretDetails: ocivault.CreateSecretDetails{
			CompartmentId: new(target.CompartmentID), VaultId: new(target.VaultID), KeyId: new(target.KeyID),
			SecretName: new(name), Description: new(description),
			SecretContent: ocivault.Base64SecretContentDetails{Content: new(content), Stage: ocivault.SecretContentDetailsStageCurrent},
		},
		// The SDK retries a lost response with the same token, which OCI
		// answers with the first result instead of a second secret.
		OpcRetryToken: new(uuid.New().String()),
	})
	if err != nil {
		if id, provisioning, lookupErr := lookup(ctx, client, target, name); lookupErr == nil && id != "" {
			stored.ID, stored.Provisioning = id, provisioning
			return stored, nil
		}
		return stored, fmt.Errorf("create Vault secret %s failed", name)
	}
	if response.Id == nil || !secretOCIDRE.MatchString(*response.Id) {
		return stored, fmt.Errorf("create Vault secret %s: OCI returned no secret OCID", name)
	}
	stored.ID, stored.Created = *response.Id, true
	return stored, nil
}

// lookup returns the OCID of the active secret name, or "" when the Vault has
// none. A secret of that name in any other state needs an operator: it may be
// pending deletion, and OCI refuses its name until it is deleted.
func lookup(ctx context.Context, client VaultClient, target Target, name string) (string, bool, error) {
	found := ""
	provisioning := false
	request := ocivault.ListSecretsRequest{CompartmentId: new(target.CompartmentID), VaultId: new(target.VaultID), Name: new(name)}
	for range 32 {
		response, err := client.ListSecrets(ctx, request)
		if err != nil {
			return "", false, fmt.Errorf("list Vault secret %s failed", name)
		}
		for _, item := range response.Items {
			if item.SecretName == nil || *item.SecretName != name {
				continue
			}
			if item.Id == nil || !secretOCIDRE.MatchString(*item.Id) || found != "" ||
				item.LifecycleState != ocivault.SecretSummaryLifecycleStateActive &&
					item.LifecycleState != ocivault.SecretSummaryLifecycleStateCreating {
				return "", false, fmt.Errorf("Vault secret %s exists in state %s; inspect it before rerunning", name, item.LifecycleState)
			}
			found = *item.Id
			provisioning = item.LifecycleState == ocivault.SecretSummaryLifecycleStateCreating
		}
		if response.OpcNextPage == nil {
			return found, provisioning, nil
		}
		request.Page = response.OpcNextPage
	}
	return "", false, fmt.Errorf("list Vault secret %s: too many pages", name)
}

func safeEnv() error {
	for _, variable := range ociclient.SecretUnsafeEnv {
		if _, set := os.LookupEnv(variable); set {
			return fmt.Errorf("OCI Vault access refuses to run while %s is set", variable)
		}
	}
	return nil
}

func retrySecretRead(err error) bool {
	var serviceErr common.ServiceError
	if !errors.As(err, &serviceErr) {
		return false
	}
	status := serviceErr.GetHTTPStatusCode()
	return status == http.StatusNotFound || status == http.StatusConflict
}

// SecretUnsafeEnv are the OCI SDK variables that print request and response
// bodies or redirect endpoints and TLS trust. Callers that move secrets
// through the SDK refuse to run while any is set.
var SecretUnsafeEnv = []string{"OCI_GO_SDK_DEBUG", "OCI_METADATA_BASE_URL", "OCI_SDK_AUTH_CLIENT_REGION_URL",
	"OCI_DEFAULT_CERTS_PATH", "OCI_DEFAULT_CLIENT_CERTS_PATH", "OCI_DEFAULT_CLIENT_CERTS_PRIVATE_KEY_PATH"}

func readSecret(ctx context.Context, client BundleClient, vaultID, cell, key string) (string, error) {
	return readBack(ctx, client, vaultID, cell, key, false)
}

// readBack reads and checks a secret that may have been created a moment ago.
func readBack(ctx context.Context, client BundleClient, vaultID, cell, key string, created bool) (string, error) {
	name := SecretName(cell, key)
	value, err := vaultsecret.ReadBack(ctx, client, vaultID, name, created)
	if err != nil {
		return "", err
	}
	if err := validSecret(key, value); err != nil {
		return "", errors.Join(fmt.Errorf("Vault secret %s", name), err)
	}
	return value, nil
}

func Read(ctx context.Context, client BundleClient, vaultID, name string) (string, error) {
	response, err := readBundle(ctx, client, vaultID, name)
	if err != nil {
		return "", err
	}
	return decodeBundle(response.SecretBundle, name)
}

func readBundle(ctx context.Context, client BundleClient, vaultID, name string) (ocisecrets.GetSecretBundleByNameResponse, error) {
	if err := safeEnv(); err != nil {
		return ocisecrets.GetSecretBundleByNameResponse{}, err
	}
	response, err := client.GetSecretBundleByName(ctx, ocisecrets.GetSecretBundleByNameRequest{
		SecretName: new(name), VaultId: new(vaultID), Stage: ocisecrets.GetSecretBundleByNameStageCurrent,
	})
	if err != nil {
		return response, &readError{name: name, cause: err}
	}
	return response, nil
}

// Keep the SDK error available for retry classification, without printing
// a response body that might contain secret material.
type readError struct {
	name  string
	cause error
}

func (e *readError) Error() string    { return "read Vault secret " + e.name + " failed" }
func (e *readError) Unwrap() error    { return e.cause }
func (e *readError) GoString() string { return e.Error() }

func decodeBundle(bundle ocisecrets.SecretBundle, name string) (string, error) {
	var content *string
	switch bundle := bundle.SecretBundleContent.(type) {
	case ocisecrets.Base64SecretBundleContentDetails:
		content = bundle.Content
	case *ocisecrets.Base64SecretBundleContentDetails:
		if bundle != nil {
			content = bundle.Content
		}
	}
	if content == nil {
		return "", fmt.Errorf("Vault secret %s has no base64 content", name)
	}
	if len(*content) > base64.StdEncoding.EncodedLen(maxValue) {
		return "", fmt.Errorf("Vault secret %s exceeds %d bytes", name, maxValue)
	}
	value, err := base64.StdEncoding.Strict().DecodeString(*content)
	if err != nil {
		return "", fmt.Errorf("Vault secret %s is not base64", name)
	}
	if len(value) > maxValue {
		return "", fmt.Errorf("Vault secret %s exceeds %d bytes", name, maxValue)
	}
	return string(value), nil
}

func ReadBack(ctx context.Context, client BundleClient, vaultID, name string, created bool) (string, error) {
	for attempt := 1; ; attempt++ {
		value, err := Read(ctx, client, vaultID, name)
		if err == nil || !created || attempt == 30 || !retrySecretRead(err) {
			return value, err
		}
		select {
		case <-ctx.Done():
			return "", ctx.Err()
		case <-time.After(2 * time.Second):
		}
	}
}

func safeEnv() error {
	for _, variable := range ociclient.SecretUnsafeEnv {
		if _, set := os.LookupEnv(variable); set {
			return fmt.Errorf("OCI Vault access refuses to run while %s is set", variable)
		}
	}
	return nil
}

func retrySecretRead(err error) bool {
	var serviceErr common.ServiceError
	if !errors.As(err, &serviceErr) {
		return false
	}
	status := serviceErr.GetHTTPStatusCode()
	return status == http.StatusNotFound || status == http.StatusConflict
}

// SecretUnsafeEnv are the OCI SDK variables that print request and response
// bodies or redirect endpoints and TLS trust. Callers that move secrets
// through the SDK refuse to run while any is set.
var SecretUnsafeEnv = []string{"OCI_GO_SDK_DEBUG", "OCI_METADATA_BASE_URL", "OCI_SDK_AUTH_CLIENT_REGION_URL",
	"OCI_DEFAULT_CERTS_PATH", "OCI_DEFAULT_CLIENT_CERTS_PATH", "OCI_DEFAULT_CLIENT_CERTS_PRIVATE_KEY_PATH"}

// Env names the test tier of the current run.
const Env = "TS_TEST_TIER"

// QualificationTier is the Env value of a pre-deploy qualification run.
const QualificationTier = "qualification"

// Qualifying reports whether this run is a T2 qualification run.
func Qualifying() bool { return os.Getenv(Env) == QualificationTier }

// Integration marks a T1 test: a multi-process lab or a slow end-to-end
// contract whose invariants T0 already covers with a single-process test.
// It skips under go test -short.
func Integration(t testing.TB) {
	t.Helper()
	if testing.Short() {
		t.Skip("integration tier: runs without -short on pushes to develop and main")
	}
}

// Qualification marks a T2 test that needs real infrastructure named by
// environment variables, and returns their values in order. When any of them
// is unset or empty the test skips, except in a qualification run, where it
// fails: the fixture the gate promised is missing.
func Qualification(t testing.TB, envs ...string) []string {
	t.Helper()
	if len(envs) == 0 {
		t.Fatal("tier.Qualification needs the environment variables that supply its fixture")
	}
	values := make([]string, len(envs))
	var missing []string
	for i, name := range envs {
		values[i] = os.Getenv(name)
		if values[i] == "" {
			missing = append(missing, name)
		}
	}
	if len(missing) > 0 {
		Unavailable(t, "qualification fixture not supplied: set %s", strings.Join(missing, ", "))
	}
	return values
}

// Unavailable reports that a T2 fixture is missing for a reason the caller
// determined itself, such as an opt-in that needs one of several variables.
// It skips the test, or fails it in a qualification run.
func Unavailable(t testing.TB, format string, args ...any) {
	t.Helper()
	if Qualifying() {
		t.Fatalf(Env+"="+QualificationTier+": "+format, args...)
	}
	t.Skipf(format, args...)
}

var assetRE = regexp.MustCompile(`^terrabase-linux-(?:amd64|arm64)$`)

// maxBinaryBytes matches the controller's artifact admission limit.
const maxBinaryBytes = 512 << 20

// VerifyRelease checks a downloaded release executable against its
// published .sha256 asset and returns the digest to pin. The checksum file
// must hold exactly one sha256sum line naming the executable's asset.
func VerifyRelease(binaryPath, checksumPath string) (string, error) {
	return VerifyAsset(binaryPath, checksumPath, assetRE)
}

// VerifyAsset is VerifyRelease for any single-file release executable whose
// asset name matches asset, such as ts-auth-linux-arm64.
func VerifyAsset(binaryPath, checksumPath string, asset *regexp.Regexp) (string, error) {
	name := filepath.Base(binaryPath)
	if !asset.MatchString(name) {
		return "", fmt.Errorf("release executable %q is not one of %s", name, asset)
	}
	checksum, err := os.ReadFile(checksumPath)
	if err != nil {
		return "", err
	}
	fields := strings.Fields(string(checksum))
	if len(fields) != 2 || bytes.Count(checksum, []byte("\n")) > 1 || strings.TrimPrefix(fields[1], "*") != name ||
		len(fields[0]) != 64 || strings.ToLower(fields[0]) != fields[0] {
		return "", fmt.Errorf("%s is not one sha256sum line for %s", checksumPath, name)
	}
	if _, err := hex.DecodeString(fields[0]); err != nil {
		return "", fmt.Errorf("%s is not one sha256sum line for %s", checksumPath, name)
	}
	file, err := os.Open(binaryPath)
	if err != nil {
		return "", err
	}
	defer file.Close()
	hash := sha256.New()
	// The asset name is the architecture the hosts run: an executable built
	// for another machine would otherwise fail only once it reached them.
	var header elf.Header64
	if err := binary.Read(io.TeeReader(file, hash), binary.LittleEndian, &header); err != nil || string(header.Ident[:4]) != elf.ELFMAG {
		return "", fmt.Errorf("%s is not an ELF executable", binaryPath)
	}
	if elf.Class(header.Ident[elf.EI_CLASS]) != elf.ELFCLASS64 || elf.Data(header.Ident[elf.EI_DATA]) != elf.ELFDATA2LSB {
		return "", fmt.Errorf("%s is not a 64-bit little-endian ELF executable", binaryPath)
	}
	want := map[string]elf.Machine{"amd64": elf.EM_X86_64, "arm64": elf.EM_AARCH64}[name[strings.LastIndexByte(name, '-')+1:]]
	if got := elf.Machine(header.Machine); got != want {
		return "", fmt.Errorf("%s must be built for %v, found %v", name, want, got)
	}
	size, err := io.Copy(hash, io.LimitReader(file, maxBinaryBytes))
	if err != nil {
		return "", err
	}
	if size+int64(binary.Size(header)) > maxBinaryBytes {
		return "", errors.New("release executable exceeds the artifact admission limit")
	}
	if digest := hex.EncodeToString(hash.Sum(nil)); digest != fields[0] {
		return "", fmt.Errorf("%s has SHA-256 %s, its release checksum says %s", name, digest, fields[0])
	}
	return fields[0], nil
}

func NewCA(cell string, now time.Time) (certificatePEM, keyPEM []byte, err error) {
	if !nameRE.MatchString(cell) {
		return nil, nil, errors.New("invalid cell name")
	}
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, nil, err
	}
	template := &x509.Certificate{
		SerialNumber: serial(), Subject: pkix.Name{CommonName: "TerraBase member CA " + cell},
		NotBefore: now.Add(-5 * time.Minute), NotAfter: now.Add(caValidity),
		KeyUsage:              x509.KeyUsageCertSign | x509.KeyUsageCRLSign,
		BasicConstraintsValid: true, IsCA: true, MaxPathLenZero: true,
	}
	der, err := x509.CreateCertificate(rand.Reader, template, template, &key.PublicKey, key)
	if err != nil {
		return nil, nil, err
	}
	keyDER, err := x509.MarshalPKCS8PrivateKey(key)
	if err != nil {
		return nil, nil, err
	}
	return pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der}),
		pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: keyDER}), nil
}

// LoadCA reads a member CA written by NewCA. The key must be a regular
// file that only this process user owns and can read.
func LoadCA(certificateFile, keyFile string) (*CA, error) {
	certificatePEM, err := os.ReadFile(certificateFile)
	if err != nil {
		return nil, err
	}
	keyPEM, err := readOwnerOnly(keyFile)
	if err != nil {
		return nil, fmt.Errorf("terrabase member CA key: %w", err)
	}
	pair, err := tls.X509KeyPair(certificatePEM, keyPEM)
	if err != nil {
		return nil, fmt.Errorf("terrabase member CA: %w", err)
	}
	certificate := pair.Leaf
	signer, ok := pair.PrivateKey.(crypto.Signer)
	if len(pair.Certificate) != 1 || !ok || !certificate.IsCA || certificate.KeyUsage&x509.KeyUsageCertSign == 0 {
		return nil, errors.New("terrabase member CA must be one CA certificate and its key")
	}
	return &CA{certificate: certificate, pem: certificatePEM, key: signer}, nil
}

// CertificatePEM is the CA certificate members trust.
func (ca *CA) CertificatePEM() []byte { return slices.Clone(ca.pem) }

// Issue signs a member's certificate request for its listed peer entry. The
// certificate names the member and its peer address, and serves both as the
// peer listener's server certificate and as the client certificate a member
// presents to other members.
func (ca *CA) Issue(csrDER []byte, peer Peer, now time.Time) ([]byte, error) {
	request, err := x509.ParseCertificateRequest(csrDER)
	if err != nil || request.CheckSignature() != nil {
		return nil, errors.New("invalid member certificate request")
	}
	if key, ok := request.PublicKey.(*ecdsa.PublicKey); !ok || key.Curve != elliptic.P256() {
		return nil, errors.New("member certificate request must use an ECDSA P-256 key")
	}
	notAfter := now.Add(memberValidity)
	if ca.certificate.NotAfter.Before(notAfter) {
		notAfter = ca.certificate.NotAfter
	}
	template := &x509.Certificate{
		SerialNumber: serial(), Subject: pkix.Name{CommonName: peer.Name},
		DNSNames: []string{peer.Name}, IPAddresses: []net.IP{peer.Address.Addr().AsSlice()},
		NotBefore: now.Add(-5 * time.Minute), NotAfter: notAfter,
		KeyUsage:    x509.KeyUsageDigitalSignature,
		ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth},
	}
	der, err := x509.CreateCertificate(rand.Reader, template, ca.certificate, request.PublicKey, ca.key)
	if err != nil {
		return nil, err
	}
	return pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der}), nil
}

// NewMemberKey creates a member's private key and the certificate request
// the host sends to the controller. The key never leaves the host.
func NewMemberKey() (keyPEM, csrDER []byte, err error) {
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, nil, err
	}
	keyDER, err := x509.MarshalPKCS8PrivateKey(key)
	if err != nil {
		return nil, nil, err
	}
	csrDER, err = x509.CreateCertificateRequest(rand.Reader, &x509.CertificateRequest{}, key)
	if err != nil {
		return nil, nil, err
	}
	return pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: keyDER}), csrDER, nil
}

func readOwnerOnly(path string) ([]byte, error) {
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), path)
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, err
	}
	owner, ok := info.Sys().(*syscall.Stat_t)
	if !info.Mode().IsRegular() || info.Mode().Perm()&0o077 != 0 || !ok || owner.Uid != uint32(os.Getuid()) {
		return nil, errors.New("must be a regular file readable only by its owner, this process user")
	}
	return io.ReadAll(io.LimitReader(file, 64<<10))
}

func serial() *big.Int {
	n, err := rand.Int(rand.Reader, new(big.Int).Lsh(big.NewInt(1), 127))
	if err != nil {
		panic(err)
	}
	return n.Add(n, big.NewInt(1))
}

type Layout string

func (l Layout) Data() string        { return filepath.Join(string(l), "data") }
func (l Layout) Bundle() string      { return filepath.Join(string(l), "bundle") }
func (l Layout) TLS() string         { return filepath.Join(string(l), "tls") }
func (l Layout) Key() string         { return filepath.Join(l.TLS(), "member.key") }
func (l Layout) Certificate() string { return filepath.Join(l.TLS(), "member.pem") }
func (l Layout) CA() string          { return filepath.Join(l.TLS(), "ca.pem") }

// Env is the member's environment: the profile settings, the host-owned paths
// and member, the member's name.
func (l Layout) Env(env map[string]string, profile Profile, member string) map[string]string {
	result := maps.Clone(env)
	result[EnvNodeName] = member
	result[EnvDataDirectory] = l.Data()
	result[EnvBundleExtract] = l.Bundle()
	result[EnvPeerCertificate] = l.Certificate()
	result[EnvPeerPrivateKey] = l.Key()
	result[EnvPeerClientCA] = l.CA()
	if profile.ClientPort != 0 {
		result[EnvClientCertificate] = l.Certificate()
		result[EnvClientPrivateKey] = l.Key()
	}
	return result
}

func Healthy(ctx context.Context, adminPort int) error {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, "http://127.0.0.1:"+strconv.Itoa(adminPort)+"/healthz", nil)
	if err != nil {
		return err
	}
	response, err := http.DefaultClient.Do(request)
	if err != nil {
		return fmt.Errorf("terrabase health: %w", err)
	}
	defer response.Body.Close()
	var body struct {
		Status string `json:"status"`
	}
	data, err := io.ReadAll(io.LimitReader(response.Body, 4096))
	if err == nil && response.StatusCode == http.StatusOK {
		err = json.Unmarshal(data, &body)
	}
	if err != nil || response.StatusCode != http.StatusOK || body.Status != "ok" {
		return fmt.Errorf("terrabase health: HTTP %d %q", response.StatusCode, strings.TrimSpace(string(data)))
	}
	return nil
}

func memberClient(clientURL, adminURL, member, caFile, credentialFile string) (TerraBase, error) {
	ca, err := os.ReadFile(caFile)
	if err != nil {
		return TerraBase{}, err
	}
	pool := x509.NewCertPool()
	if !pool.AppendCertsFromPEM(ca) {
		return TerraBase{}, errors.New("--member-ca holds no PEM certificate")
	}
	credential, err := readOwnerOnly(credentialFile, 4096)
	if err != nil {
		return TerraBase{}, fmt.Errorf("--dashboard-credential-file: %w", err)
	}
	if !strings.HasPrefix(clientURL, "https://") || !strings.HasPrefix(adminURL, "http://") {
		return TerraBase{}, errors.New("--client-url must be https:// and --admin-url http://")
	}
	transport := http.DefaultTransport.(*http.Transport).Clone()
	transport.TLSClientConfig = &tls.Config{RootCAs: pool, ServerName: member, MinVersion: tls.VersionTLS12}
	// A member or forward that accepts but stalls must not hang the command.
	return TerraBase{HTTP: &http.Client{Transport: transport, Timeout: terraBaseRequestTimeout,
		CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }}, ClientURL: strings.TrimSuffix(clientURL, "/"),
		AdminURL: strings.TrimSuffix(adminURL, "/"), Credential: strings.TrimSpace(string(credential))}, nil
}

// readOwnerOnly reads a regular file that only its owner can read.
func readOwnerOnly(path string, limit int64) ([]byte, error) {
	file, err := os.OpenFile(path, os.O_RDONLY|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, err
	}
	if !info.Mode().IsRegular() || info.Mode().Perm()&0o077 != 0 || info.Size() > limit {
		return nil, errors.New("must be a regular owner-only file")
	}
	return io.ReadAll(io.LimitReader(file, limit))
}

func writeFile(t *testing.T, content string, mode os.FileMode) string {
	path := filepath.Join(t.TempDir(), "file")
	if err := os.WriteFile(path, []byte(content), mode); err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(path, mode); err != nil {
		t.Fatal(err)
	}
	return path
}

func startTerraBase(t *testing.T, binary string, env map[string]string, adminPort int) string {
	t.Helper()
	command := exec.Command(binary)
	command.Env = []string{"HOME=/", "LANG=C", "PATH=/usr/bin:/bin"}
	for key, value := range env {
		command.Env = append(command.Env, key+"="+value)
	}
	log := filepath.Join(t.TempDir(), "terrabase.log")
	file, err := os.Create(log)
	if err != nil {
		t.Fatal(err)
	}
	defer file.Close()
	command.Stdout, command.Stderr = file, file
	if err := command.Start(); err != nil {
		t.Fatal(err)
	}
	exited := make(chan error, 1)
	go func() { exited <- command.Wait() }()
	t.Cleanup(func() {
		_ = command.Process.Signal(syscall.SIGTERM)
		select {
		case <-exited:
		case <-time.After(40 * time.Second):
			_ = command.Process.Kill()
		}
	})
	deadline := time.After(60 * time.Second)
	for {
		err := terrabase.Healthy(t.Context(), adminPort)
		if err == nil {
			return log
		}
		select {
		case exit := <-exited:
			t.Fatalf("terrabase exited before it was healthy: %v\n%s", exit, readLog(log))
		case <-deadline:
			t.Fatalf("terrabase never became healthy: %v\n%s", err, readLog(log))
		case <-time.After(100 * time.Millisecond):
		}
	}
}

func readLog(path string) string {
	data, _ := os.ReadFile(path)
	return string(data)
}

func freePort(t *testing.T) int {
	t.Helper()
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	defer listener.Close()
	return listener.Addr().(*net.TCPAddr).Port
}

func bootstrap(ctx context.Context, terraBase TerraBase, client VaultClient, bundles BundleClient, target Target, cell string, output io.Writer) (string, error) {
	organization := ""
	for _, project := range Projects {
		tenant, secrets, err := bootstrapProject(ctx, terraBase, client, bundles, target, cell, project)
		if err != nil {
			return "", fmt.Errorf("project %s: %w", project.Name, err)
		}
		if err := printLine(output, map[string]any{"tenant": tenant, "secrets": secrets}); err != nil {
			return "", err
		}
		organization = tenant.OrganizationID
	}
	return organization, nil
}

// bootstrapProject ensures project's tenant and stores its project ID and,
// only when the Vault holds none, a newly issued API key. It then reads both
// back: a project ID or key of an earlier run must still name this tenant
// and reach its database, or it fails instead of reporting a stale tenant.
func bootstrapProject(ctx context.Context, terraBase TerraBase, client VaultClient, bundles BundleClient, target Target, cell string, project Project) (Tenant, []Stored, error) {
	tenant, err := terraBase.EnsureTenant(ctx, project)
	if err != nil {
		return Tenant{}, nil, err
	}
	projectID, err := Ensure(ctx, client, target, cell, project.ProjectIDKey, func(context.Context) (string, error) {
		return tenant.ProjectID, nil
	})
	if err != nil {
		return Tenant{}, nil, err
	}
	// A stale project ID must stop the command before a key is issued:
	// TerraBase cannot revoke one.
	storedID, err := readBack(ctx, bundles, target.VaultID, cell, project.ProjectIDKey, projectID.Created || projectID.Provisioning)
	if err != nil {
		return Tenant{}, nil, err
	}
	if storedID != tenant.ProjectID {
		return Tenant{}, nil, fmt.Errorf("Vault secret %s names project %s, TerraBase has %s; inspect both before rerunning", projectID.Secret, storedID, tenant.ProjectID)
	}
	key, err := Ensure(ctx, client, target, cell, project.APIKeyKey, func(ctx context.Context) (string, error) {
		return terraBase.IssueKey(ctx, tenant)
	})
	if err != nil {
		return Tenant{}, nil, err
	}
	apiKey, err := readBack(ctx, bundles, target.VaultID, cell, project.APIKeyKey, key.Created || key.Provisioning)
	if err != nil {
		return Tenant{}, nil, err
	}
	if err := terraBase.CheckKey(ctx, tenant, apiKey); err != nil {
		return Tenant{}, nil, fmt.Errorf("Vault secret %s does not reach database %s: %w", key.Secret, tenant.Database, err)
	}
	return tenant, []Stored{projectID, key}, nil
}

// own makes the ts-auth user whose verified address is email the
// organization's owner, keeping BootstrapUser as an admin, and prints
// {"organization_id":...,"owner":...,"admin":...,"steps":[...]}. A rerun
// takes no step.
func own(ctx context.Context, terraBase TerraBase, users TSAuthUsers, organization, email string, output io.Writer) error {
	owner, err := users.UserID(ctx, email)
	if err != nil {
		return err
	}
	steps, err := terraBase.EnsureOwner(ctx, organization, owner, email)
	if err != nil {
		return fmt.Errorf("%w (steps taken: %v)", err, steps)
	}
	return printLine(output, map[string]any{"organization_id": organization, "owner": owner, "admin": terraBase.user(), "steps": steps})
}

func (u TSAuthUsers) UserID(ctx context.Context, email string) (string, error) {
	type user struct {
		ID            string `json:"id"`
		Email         string `json:"email"`
		EmailVerified bool   `json:"email_verified"`
		Anonymous     bool   `json:"is_anonymous"`
		Banned        bool   `json:"banned"`
	}
	var found []user
	for after := ""; ; {
		query := url.Values{"limit": {"100"}}
		if after != "" {
			query.Set("starting_after", after)
		}
		var page struct {
			Data []user `json:"data"`
		}
		target := u.URL + "/v1/" + url.PathEscape(u.Instance) + "/users?" + query.Encode()
		if err := (TerraBase{HTTP: u.HTTP}).call(ctx, http.MethodGet, target, http.Header{"Authorization": {"Bearer " + u.Key}}, nil, http.StatusOK, &page); err != nil {
			return "", fmt.Errorf("list ts-auth users: %w", err)
		}
		for _, item := range page.Data {
			if !entityid.Valid(item.ID) {
				return "", errors.New("ts-auth returned a noncanonical user ID")
			}
			if strings.EqualFold(item.Email, email) {
				found = append(found, item)
			}
		}
		if len(page.Data) < 100 || page.Data[len(page.Data)-1].ID == after {
			break
		}
		after = page.Data[len(page.Data)-1].ID
	}
	switch {
	case len(found) == 0:
		return "", fmt.Errorf("ts-auth instance %s has no user %s yet: sign in once with that address (for example on the dashboard), then rerun", u.Instance, email)
	case len(found) > 1:
		return "", fmt.Errorf("ts-auth instance %s has %d users %s; resolve that before rerunning", u.Instance, len(found), email)
	}
	owner := found[0]
	if !owner.EmailVerified || owner.Anonymous || owner.Banned {
		return "", fmt.Errorf("ts-auth user %s must have verified %s and be neither anonymous nor banned", owner.ID, email)
	}
	if !entityid.Valid(owner.ID) || owner.ID == BootstrapUser {
		return "", fmt.Errorf("ts-auth user %s has an unusable id", email)
	}
	return owner.ID, nil
}

func printLine(output io.Writer, value any) error {
	if err := json.MarshalWrite(output, value); err != nil {
		return err
	}
	_, err := fmt.Fprintln(output)
	return err
}

func (t TerraBase) EnsureTenant(ctx context.Context, project Project) (Tenant, error) {
	organizations := "/v1/management/organizations"
	organization, err := t.ensure(ctx, "", organizations, OrganizationName)
	if err != nil {
		return Tenant{}, fmt.Errorf("organization: %w", err)
	}
	projects := organizations + "/" + url.PathEscape(organization) + "/projects"
	projectID, err := t.ensure(ctx, organization, projects, project.Name)
	if err != nil {
		return Tenant{}, fmt.Errorf("project: %w", err)
	}
	database, err := t.ensure(ctx, organization, projects+"/"+url.PathEscape(projectID)+"/databases", project.Database)
	if err != nil {
		return Tenant{}, fmt.Errorf("database: %w", err)
	}
	return Tenant{OrganizationID: organization, Project: project.Name, ProjectID: projectID, DatabaseID: database, Database: project.Database}, nil
}

func (t TerraBase) ensure(ctx context.Context, organization, path, name string) (string, error) {
	// find returns the ID of the one item named name, or "" when none is.
	find := func() (string, error) {
		items, err := list[named](ctx, t, organization, path)
		if err != nil {
			return "", err
		}
		found := ""
		for _, item := range items {
			if item.Name != name {
				continue
			}
			if found != "" {
				return "", fmt.Errorf("two named %q; remove one first", name)
			}
			if !entityid.Valid(item.ID) {
				return "", errors.New("TerraBase returned a noncanonical entity ID")
			}
			found = item.ID
		}
		return found, nil
	}
	found, err := find()
	if err != nil {
		return "", err
	}
	if found != "" {
		return found, nil
	}
	var created named
	if err := t.management(ctx, http.MethodPost, organization, path, map[string]string{"name": name}, http.StatusCreated, &created); err != nil {
		if recovered, recoverErr := find(); recoverErr == nil && recovered != "" {
			return recovered, nil
		} else if recoverErr != nil {
			return "", recoverErr
		}
		return "", err
	}
	if !entityid.Valid(created.ID) || created.Name != name {
		return "", fmt.Errorf("TerraBase created %q without its ID", name)
	}
	return created.ID, nil
}

// list reads every page of a Management collection.
func list[T any](ctx context.Context, t TerraBase, organization, path string) ([]T, error) {
	var items []T
	for after := ""; ; {
		query := url.Values{"limit": {"100"}}
		if after != "" {
			query.Set("after", after)
		}
		var page struct {
			Items []T     `json:"items"`
			Next  *string `json:"next"`
		}
		if err := t.management(ctx, http.MethodGet, organization, path+"?"+query.Encode(), nil, http.StatusOK, &page); err != nil {
			return nil, err
		}
		items = append(items, page.Items...)
		if page.Next == nil || *page.Next == "" || len(page.Items) == 0 {
			return items, nil
		}
		after = *page.Next
	}
}

// user is the acting user.
func (t TerraBase) user() string {
	if t.User == "" {
		return BootstrapUser
	}
	return t.User
}

func (t TerraBase) management(ctx context.Context, method, organization, path string, body any, status int, result any) error {
	if !entityid.Valid(t.user()) || organization != "" && !entityid.Valid(organization) {
		return errors.New("TerraBase acting user must be a canonical uppercase ULID")
	}
	headers := http.Header{"Authorization": {"Bearer " + t.Credential}, "X-TerraBase-User-Id": {t.user()}}
	if organization != "" {
		headers.Set("X-TerraBase-Organization-Id", organization)
	}
	base := t.ClientURL
	if t.ManagementOnAdmin {
		base = t.AdminURL
	}
	return t.call(ctx, method, base+path, headers, body, status, result)
}

// IssueKey issues the tenant's documents:read/write API key, named after its
// project and narrowed to its database, through the admin listener. The
// secret is returned, never printed.
func (t TerraBase) IssueKey(ctx context.Context, tenant Tenant) (string, error) {
	var issued struct {
		Secret string `json:"secret"`
	}
	request := map[string]any{"name": tenant.Project, "scopes": KeyScopes, "organizationId": tenant.OrganizationID,
		"projectId": tenant.ProjectID, "databaseId": tenant.DatabaseID}
	if err := t.call(ctx, http.MethodPost, t.AdminURL+"/admin/api-keys", http.Header{}, request, http.StatusCreated, &issued); err != nil {
		return "", fmt.Errorf("issue %s API key: %w", tenant.Project, err)
	}
	if err := validSecret(EnvAPIKey, issued.Secret); err != nil {
		return "", errors.New("TerraBase issued an unusable API key")
	}
	return issued.Secret, nil
}

// CheckKey proves that key reaches the tenant's database: it lists the
// database's collections, which needs documents:read.
func (t TerraBase) CheckKey(ctx context.Context, tenant Tenant, key string) error {
	var collections any
	path := "/v1/projects/" + url.PathEscape(tenant.ProjectID) + "/databases/" + url.PathEscape(tenant.Database) + "/collections"
	return t.call(ctx, http.MethodGet, t.ClientURL+path, http.Header{"Authorization": {"Bearer " + key}}, nil, http.StatusOK, &collections)
}

// EnsureOwner makes owner, the ts-auth user whose verified address is email,
// the organization's owner and keeps the acting user, BootstrapUser, as an
// admin. As the acting user it adds owner as a member and offers it the
// ownership; as owner it confirms the transfer and, since confirming leaves
// the acting user a member, makes it an admin again. Each step runs only
// while the members show it undone, so a rerun changes nothing. It returns
// the steps it took. Adding a member with the credential needs TerraBase
// TS-535 and so the admin listener: the credential carries no verified
// email, so it cannot accept an invitation.
func (t TerraBase) EnsureOwner(ctx context.Context, organization, owner, email string) ([]string, error) {
	if !entityid.Valid(organization) || !entityid.Valid(owner) || owner == BootstrapUser {
		return nil, errors.New("TerraBase owner must be a canonical uppercase user ULID distinct from the bootstrap actor")
	}
	nominee := t
	nominee.User = owner
	path := "/v1/management/organizations/" + url.PathEscape(organization)
	roles, err := t.roles(ctx, organization)
	if err != nil {
		return nil, fmt.Errorf("list members: %w", err)
	}
	// Only the acting user hands the organization over: once another user owns
	// it, a rerun with a different address must not add that user, since any
	// member manages every project and database.
	if roles[owner] != "owner" && roles[t.user()] != "owner" {
		return nil, fmt.Errorf("organization %s is owned by another user; refusing to add %s", organization, owner)
	}
	var steps []string
	if roles[owner] == "" {
		add := path + "/members/" + url.PathEscape(owner)
		if err := t.management(ctx, http.MethodPut, organization, add, map[string]string{"email": email}, http.StatusOK, nil); err != nil {
			return steps, fmt.Errorf("add %s as a member: %w", owner, err)
		}
		steps = append(steps, "added")
	}
	if roles[owner] != "owner" {
		transfer := path + "/ownership-transfer"
		if err := t.management(ctx, http.MethodPost, organization, transfer, map[string]string{"userId": owner}, http.StatusCreated, nil); err != nil {
			return steps, fmt.Errorf("offer the ownership to %s: %w", owner, err)
		}
		if err := nominee.management(ctx, http.MethodPost, organization, transfer+"/confirm", nil, http.StatusOK, nil); err != nil {
			return steps, fmt.Errorf("confirm the ownership as %s: %w", owner, err)
		}
		steps = append(steps, "transferred")
		if roles, err = nominee.roles(ctx, organization); err != nil {
			return steps, fmt.Errorf("list members: %w", err)
		}
	}
	if roles[t.user()] != "admin" {
		role := path + "/members/" + url.PathEscape(t.user()) + "/role"
		if err := nominee.management(ctx, http.MethodPut, organization, role, map[string]string{"role": "admin"}, http.StatusOK, nil); err != nil {
			return steps, fmt.Errorf("keep %s as admin: %w", t.user(), err)
		}
		steps = append(steps, "kept "+t.user()+" as admin")
	}
	return steps, nil
}

// roles maps each member of the organization to its role.
func (t TerraBase) roles(ctx context.Context, organization string) (map[string]string, error) {
	members, err := list[struct {
		UserID string `json:"userId"`
		Role   string `json:"role"`
	}](ctx, t, organization, "/v1/management/organizations/"+url.PathEscape(organization)+"/members")
	if err != nil {
		return nil, err
	}
	roles := make(map[string]string, len(members))
	for _, member := range members {
		if !entityid.Valid(member.UserID) {
			return nil, errors.New("TerraBase returned a noncanonical user ID")
		}
		roles[member.UserID] = member.Role
	}
	return roles, nil
}

// call sends one JSON request and decodes the reply into result, unless it
// is nil. An error carries the method, path and status only: response bodies
// may echo a request, and requests carry credentials.
func (t TerraBase) call(ctx context.Context, method, target string, headers http.Header, body any, status int, result any) error {
	var reader io.Reader
	if body != nil {
		data, err := json.Marshal(body)
		if err != nil {
			return err
		}
		reader = bytes.NewReader(data)
		headers.Set("Content-Type", "application/json")
	}
	request, err := http.NewRequestWithContext(ctx, method, target, reader)
	if err != nil {
		return err
	}
	request.Header = headers
	client := t.HTTP
	if client == nil {
		client = http.DefaultClient
	}
	path := request.URL.Path
	response, err := client.Do(request)
	if err != nil {
		return err
	}
	defer response.Body.Close()
	if response.StatusCode != status {
		return fmt.Errorf("%s %s: HTTP %d", method, path, response.StatusCode)
	}
	if result == nil {
		return nil
	}
	if err := json.UnmarshalRead(io.LimitReader(response.Body, 1<<20), result); err != nil {
		return fmt.Errorf("%s %s: decode reply: %w", method, path, err)
	}
	return nil
}

type currentBundle struct {
	response ocisecrets.GetSecretBundleByNameResponse
	err      error
}

func (b currentBundle) GetSecretBundleByName(_ context.Context, request ocisecrets.GetSecretBundleByNameRequest) (ocisecrets.GetSecretBundleByNameResponse, error) {
	if request.Stage != ocisecrets.GetSecretBundleByNameStageCurrent {
		return ocisecrets.GetSecretBundleByNameResponse{}, errors.New("read did not request CURRENT")
	}
	return b.response, b.err
}

